(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035-t*0.5)*8 + Math.cos((y+w1y)*0.028+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.032+t*0.45)*8 + Math.sin((x+w1x)*0.025-t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*55, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*65, 0.13, 1.8, 1.05],
    [200+Math.sin(t*0.25+5)*110, 220+Math.cos(t*0.45+3)*45, 0.075, 2.4, 1.15]
  ];
  let aS=0, iS=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const att = w/(1+d*0.003);
    aS += Math.sin(d*f-t*sp)*att;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*att;
    iS2 += Math.sin(d*f*1.4-t*sp*0.4+3.0)*att*0.5;
  }
  const act=aS/9, inh=iS/9, inh2=iS2/9;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*Math.cos(t*0.2)+sy*0.06*Math.sin(t*0.15)+t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.03-ang*5+t*0.8)*0.2;
  const micro = (Math.sin(sx*0.45+t*3.2)*Math.sin(sy*0.45-t*2.8)+Math.sin(sx*0.3-sy*0.3+t*4))*0.12;
  const rd1 = act - inh*0.7 - inh2*0.3;
  const rd2 = rd1 + bg*0.3 + spiral + micro;
  const reaction = Math.tanh(rd2*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const veins = Math.tanh(Math.abs(Math.sin(sx*0.08+sy*0.06+t*0.7))+Math.abs(Math.cos(sx*0.05-sy*0.09-t*0.5))-1.2)*0.2;
  const blend = reaction*0.6 + cell*0.2 + veins*0.2;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,48],[10,35,82],[12,65,108],[18,105,125],
    [30,155,145],[120,190,130],[210,195,75],[230,145,55],
    [195,80,60],[140,40,65],[75,18,55],[25,10,42],[5,12,48]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const r1=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g1=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b1=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.7?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow=Math.max(0, Math.abs(reaction)-0.6)*2.5;
  return [
    Math.min(255, (r1*lum*edge+glow*30)|0),
    Math.min(255, (g1*lum*edge+glow*20)|0),
    Math.min(255, (b1*lum*edge+glow*40)|0)
  ];
}
